sysevent_script_action.script:
(function() {

	var userId = event.getValue('parm1');	// User ID but not sysId
	var userIP = event.getValue('parm2');
	const userGr = new GlideRecord('sys_user');
	userGr.get('user_name', userId);

	var userSysId = userGr.getUniqueValue();

	gs.info('Tracking start for ' + userId);

	if(!userSysId || !userIP) 
		return;

	var isAuthorized = _isAuthorizedIP(userIP);
	var existingLog = _getExistingLog(userGr.getUniqueValue(), userIP, isAuthorized);

	if(existingLog) {
		gs.info('Tracking : User log exists');

		_handleDuplicate(
			existingLog, 
			userSysId, 
			userIP, 
			isAuthorized
		);
	} else {
		gs.info('Tracking : User log does not exist');

		_createIPLog(userSysId, userIP, isAuthorized);

		if(!isAuthorized) 
			_sendUnauthorizedEmail(userSysId, userIP);
	}

	// ---------------------------------------------

	function _isAuthorizedIP(userIp) {
		var gr = new GlideRecord('u_authorized_ips');
		gr.addQuery('u_ip', userIp);
		gr.setLimit(1);
		gr.query();

		return gr.hasNext();
	}

	function _getExistingLog(userId, ip, authorized) {
		var gr = new GlideRecord('u_ip_log');
		gr.addQuery('u_user', userId);
		gr.addQuery('u_ip', ip);
		gr.addQuery('u_authorized', authorized);

		gr.setLimit(1);
		gr.query();

		return gr.next() ? gr : null;
	}

	function _handleDuplicate(existingLog, userId, ip, isAuthorized) {
		existingLog.setForceUpdate(true);
		existingLog.update();

		if(!isAuthorized) {
			_sendUnauthorizedEmail(userId, ip);
		}
	}

	function _sendUnauthorizedEmail(userId, ip, recipientAddress = 'nickinguel@proton.me') 
	{
		var user = _getUserDetails(userId);

		if(!user) 
			return;

		gs.eventQueue('onboarding.user.login', userGr, ip, recipientAddress);

		gs.info(`Tracking : Email sent to ${recipientAddress}`);
	}

	function _getUserDetails(userId) {
		var user = new GlideRecord('sys_user');

		return user.get(userId) 
			? {
				// email: user.getValue('email'),
				name: user.getDisplayValue('name')
			} 
			: null;
	}

	function _createIPLog(userId, ip, authorized) {
		var gr = new GlideRecord('u_ip_log');

		gr.initialize();
		gr.setValue('u_user', userId);
		gr.setValue('u_ip', ip);
		gr.setValue('u_authorized', authorized);
		gr.insert();
	}

})();
